'use client';

import React from 'react';

interface JsonLdProps {
    data: any;
}

const JsonLd = ({ data }: JsonLdProps) => {
    return (
        <script
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: JSON.stringify(data).replace(/</g, '\\u003c') }}
        />
    );
};

export default JsonLd;
